// Des: Canary: check every job's labels exist on live page
// Flo: collect jobs from registry > check page-level keys > open one chat (read) > check chat-level keys > one line per job
// I/O: Sess + optional job name (caller) > Report: ok jobs in prev, drifted jobs in skip, lines
// ===================================================================
const std = @import("std"); const sess = @import("ru-sess-ctxz.zig"); const rd = @import("ru-chat-read.zig"); const rec = @import("ru-reci-main.zig"); const fnd = @import("ru-labl-find.zig"); const lab = @import("cf-labl-load.zig"); const snap = @import("ru-page-snap.zig");
fn bad(ses: *sess.Sess, nodes: []const snap.Node, keys: []const []const u8, out: *std.ArrayList(u8)) !u32 { var cnt: u32 = 0; for (keys) |key| { if (!fnd.present(&ses.reg, nodes, key)) { if (cnt > 0) try out.appendSlice(ses.aren, ","); try out.appendSlice(ses.aren, key); cnt += 1; } } return cnt; }
fn pickChat(ses: *sess.Sess) !?[]const u8 { const chats = try rd.listChats(ses); const cloud = ses.reg.get("cloud_chat"); for (chats) |cht| { if (cht.stran) continue; if (cloud) |ent| { var skip = false; for (ent.vi) |nam| { if (std.ascii.eqlIgnoreCase(nam, cht.name)) skip = true; } for (ent.en) |nam| { if (std.ascii.eqlIgnoreCase(nam, cht.name)) skip = true; } if (skip) continue; } return cht.name; } return null; }
pub fn chromeMajor(ua: []const u8) ?u32 { const idx = std.mem.find(u8, ua, "Chrome/") orelse return null; var end = idx + 7; while (end < ua.len and std.ascii.isDigit(ua[end])) end += 1; return std.fmt.parseInt(u32, ua[idx + 7 .. end], 10) catch null; }
pub fn run(ses: *sess.Sess, only: []const u8) !rec.Report { var rep: rec.Report = .{}; var lines: std.ArrayList([]const u8) = .empty; if (only.len == 0) { const ua = snap.evalStr(ses.aren, ses.conn, "navigator.userAgent") catch ""; if (chromeMajor(ua)) |maj| { if (maj >= ses.cfg.brow_vers_minz) { rep.prev += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "ok: chrome {d}", .{maj})); } else { rep.skip += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "MISSING chrome: version {d} is older than {d}", .{ maj, ses.cfg.brow_vers_minz })); } } else { rep.skip += 1; try lines.append(ses.aren, "MISSING chrome: version unknown"); } } const rest = try ses.nodes(); var states: std.ArrayList(std.ArrayList(u8)) = .empty; var names: std.ArrayList([]const u8) = .empty; var needs = false; var it = ses.reg.jobs.map.iterator(); while (it.next()) |ent| { if (only.len > 0 and !std.mem.eql(u8, only, ent.key_ptr.*)) continue; var buf: std.ArrayList(u8) = .empty; _ = try bad(ses, rest, ent.value_ptr.rest, &buf); try states.append(ses.aren, buf); try names.append(ses.aren, ent.key_ptr.*); if (ent.value_ptr.chat.len > 0) needs = true; }
if (only.len > 0 and names.items.len == 0) return error.BadJob; var chatn: ?[]const u8 = null; var shot2: []const snap.Node = &.{}; if (needs) { try ses.pre(.read); chatn = try pickChat(ses); if (chatn) |nam| { _ = try rd.openChat(ses, nam); shot2 = try ses.nodes(); } }
var idx: usize = 0; var it2 = ses.reg.jobs.map.iterator(); while (it2.next()) |ent| { if (only.len > 0 and !std.mem.eql(u8, only, ent.key_ptr.*)) continue; var buf = states.items[idx]; idx += 1; if (ent.value_ptr.chat.len > 0) { if (chatn == null) { try buf.appendSlice(ses.aren, if (buf.items.len > 0) ",no-chat" else "no-chat"); } else { var sub: std.ArrayList(u8) = .empty; const cnt = try bad(ses, shot2, ent.value_ptr.chat, &sub); if (cnt > 0) { if (buf.items.len > 0) try buf.appendSlice(ses.aren, ","); try buf.appendSlice(ses.aren, sub.items); } } }
if (buf.items.len == 0) { rep.prev += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "ok: {s}", .{ent.key_ptr.*})); } else { rep.skip += 1; try lines.append(ses.aren, try std.fmt.allocPrint(ses.aren, "MISSING {s}: {s}", .{ ent.key_ptr.*, buf.items })); } }
rep.lines = lines.items; return rep; }
